const item = $input.first().json;
const lineItems = item.lineItems || [];
const assumptions = item.clarifyingAssumptions || [];
const totals = item.totals || {};

const fmtMoney = (n) => {
  if (n === null || n === undefined || isNaN(n)) return 'N/A';
  return '$' + Number(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

const lineItemsTableRowsHtml = lineItems.map((li) => {
  return '<tr><td class="item-desc">' + li.description + '</td><td class="item-qty">' + li.quantity + ' ' + li.unit + '</td><td class="item-rate">' + fmtMoney(li.unitRate) + '</td><td class="item-total">' + fmtMoney(li.lineTotal) + '</td></tr>';
}).join('\n');

const assumptionsListHtml = assumptions.length
  ? assumptions.map((a) => '<li>' + a + '</li>').join('\n')
  : '<li>No additional assumptions were required beyond the details provided.</li>';

const now = new Date();
const generatedDateStr = now.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
const validUntil = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
const validUntilStr = validUntil.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
const companyInitial = (item.brandName || item.companyName || 'Q').trim().charAt(0).toUpperCase();

return [{
  json: Object.assign({}, item, {
    lineItemsTableRowsHtml: lineItemsTableRowsHtml,
    assumptionsListHtml: assumptionsListHtml,
    subtotalFmt: fmtMoney(totals.subtotal),
    discountAmountFmt: fmtMoney(totals.discountAmount),
    discountPct: totals.discountPct || 0,
    grandTotalFmt: fmtMoney(totals.grandTotal),
    generatedDateStr: generatedDateStr,
    validUntilStr: validUntilStr,
    companyInitial: companyInitial,
  }),
}];

